by_from.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'email-message' && doc.from) {
    emit(doc.from, doc._id);
  }
}

by_to.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'email-message' && doc.to) {
    emit(doc.to, doc._id);
  }
}

by_subject.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'email-message' && doc.subject) {
    emit(doc.subject, doc._id);
  }
}

by_participant.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'email-message') {
    if (doc.from) emit(doc.from, doc._id);
    if (doc.to) emit(doc.to, doc._id);
  }
}
